/* ── ADOPTION LOOP KILL (defect found in Paul's visual pass, 15 Aug 2026) ──
   A foreign/legacy writer sharing the storage prefix can strip the stored blob's rev while the
   mirror record keeps one; without the refreshOrg self-heal the tab adopts every poll forever.
   Contract: one adoption settles the comparison; the second checkRemote is quiet. */
(function(){
  var oid=G.currentOrgId;
  var raw=G.localStorage.getItem('architecture-org-data::'+oid);
  ok(!!raw, 'LOOP: fixture blob present for the strip');
  var blob=JSON.parse(raw); delete blob.rev; delete blob.schemaVersion;
  G.localStorage.setItem('architecture-org-data::'+oid, JSON.stringify(blob));
  G.loadData(); // boot-on-stripped-blob: in-memory rev now undefined
  var first=G.Store.checkRemote();
  var second=G.Store.checkRemote();
  ok(first===true, 'LOOP: first poll after a foreign rev-less write adopts once');
  ok(second===false, 'LOOP: second poll is quiet - the adoption self-heals the rev');
  eq(G.data.rev, G.Store.orgRev(oid), 'LOOP: healed in-memory rev matches the mirror');
  G.Store.writeOrg(oid, G.data); // restore a properly stamped blob for any later sections
})();

